// ==========================================
// وظائف البحث والاسترجاع المساعدة (Catalog Helper APIs)
// ==========================================

/**
 * جلب فحص معملي بالمفتاح أو الكود
 */
MedicalCatalog.getLabTest = function(keyOrCode) {
    if (!keyOrCode) return null;
    const q = String(keyOrCode).toLowerCase().trim();
    return MedicalCatalog.labTests.find(t => 
        (t.key && t.key.toLowerCase() === q) || 
        (t.id && String(t.id).toLowerCase() === q) || 
        (t.code && t.code.toLowerCase() === q)
    ) || null;
};

/**
 * البحث في التحاليل المعملية مع تصفية حسب القسم
 */
MedicalCatalog.searchLabTests = function(query, category) {
    let results = MedicalCatalog.labTests;
    if (category && category !== 'all') {
        results = results.filter(t => t.category === category);
    }
    if (query && query.trim()) {
        const q = query.trim().toLowerCase();
        results = results.filter(t => 
            (t.name && t.name.toLowerCase().includes(q)) ||
            (t.name_ar && t.name_ar.toLowerCase().includes(q)) ||
            (t.name_en && t.name_en.toLowerCase().includes(q)) ||
            (t.code && t.code.toLowerCase().includes(q)) ||
            (t.key && t.key.toLowerCase().includes(q)) ||
            (t.tube && t.tube.toLowerCase().includes(q))
        );
    }
    return results;
};

/**
 * جلب فحص أشعة بالمفتاح أو الكود
 */
MedicalCatalog.getRadiologyExam = function(keyOrCode) {
    if (!keyOrCode) return null;
    const q = String(keyOrCode).toLowerCase().trim();
    return MedicalCatalog.radiologyExams.find(r => 
        (r.key && r.key.toLowerCase() === q) || 
        (r.id && String(r.id).toLowerCase() === q) || 
        (r.code && r.code.toLowerCase() === q)
    ) || null;
};

/**
 * البحث في فحوصات الأشعة مع تصفية حسب الجهاز (Modality)
 */
MedicalCatalog.searchRadiologyExams = function(query, modality) {
    let results = MedicalCatalog.radiologyExams;
    if (modality && modality !== 'all') {
        results = results.filter(r => r.modality === modality || r.category === modality);
    }
    if (query && query.trim()) {
        const q = query.trim().toLowerCase();
        results = results.filter(r => 
            (r.name && r.name.toLowerCase().includes(q)) ||
            (r.name_ar && r.name_ar.toLowerCase().includes(q)) ||
            (r.name_en && r.name_en.toLowerCase().includes(q)) ||
            (r.code && r.code.toLowerCase().includes(q)) ||
            (r.body_part && r.body_part.toLowerCase().includes(q)) ||
            (r.body_part_ar && r.body_part_ar.toLowerCase().includes(q)) ||
            (r.indications && r.indications.toLowerCase().includes(q))
        );
    }
    return results;
};

/**
 * جلب دواء بالكود أو المعرف أو الاسم التجاري
 */
MedicalCatalog.getMedication = function(idOrCode) {
    if (!idOrCode) return null;
    const q = String(idOrCode).toLowerCase().trim();
    return MedicalCatalog.medications.find(m => 
        (m.id && String(m.id).toLowerCase() === q) || 
        (m.code && m.code.toLowerCase() === q) ||
        (m.trade_name && m.trade_name.toLowerCase() === q) ||
        (m.barcode && m.barcode === q)
    ) || null;
};

/**
 * البحث في كتالوج الأدوية
 */
MedicalCatalog.searchMedications = function(query, category) {
    let results = MedicalCatalog.medications;
    if (category && category !== 'all') {
        results = results.filter(m => m.category === category);
    }
    if (query && query.trim()) {
        const q = query.trim().toLowerCase();
        results = results.filter(m => 
            (m.name && m.name.toLowerCase().includes(q)) ||
            (m.trade_name && m.trade_name.toLowerCase().includes(q)) ||
            (m.trade_name_ar && m.trade_name_ar.toLowerCase().includes(q)) ||
            (m.generic_name && m.generic_name.toLowerCase().includes(q)) ||
            (m.code && m.code.toLowerCase().includes(q)) ||
            (m.barcode && m.barcode.includes(q))
        );
    }
    return results;
};

/**
 * جلب إجراء عيادة بالكود
 */
MedicalCatalog.getClinicProcedure = function(code) {
    if (!code) return null;
    const q = String(code).toLowerCase().trim();
    return MedicalCatalog.clinicProcedures.find(p => p.code && p.code.toLowerCase() === q) || null;
};

/**
 * إحصائيات عامة عن الكتالوج الطبي
 */
MedicalCatalog.getStats = function() {
    return {
        totalLabTests: MedicalCatalog.labTests.length,
        totalRadiologyExams: MedicalCatalog.radiologyExams.length,
        totalMedications: MedicalCatalog.medications.length,
        totalClinicProcedures: MedicalCatalog.clinicProcedures.length,
        totalDiagnosticCenters: MedicalCatalog.diagnosticCenters.length,
        grandTotalEntries: MedicalCatalog.labTests.length + MedicalCatalog.radiologyExams.length + MedicalCatalog.medications.length + MedicalCatalog.clinicProcedures.length + MedicalCatalog.diagnosticCenters.length
    };
};

// إتاحة الكتالوج الطبي في النطاق العام للنافذة
if (typeof window !== 'undefined') {
    window.MedicalCatalog = MedicalCatalog;
}
